import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export function showRedox(kind,t=null,reveal=false){const electron=kind==='electrons',metal=typeof t==='string'?t:'Zn';renderDiagram(electron?'Donated = accepted':'Position sets the extraction route',electron?(reveal?`${metal} + Cu²⁺ → ${metal}²⁺ + Cu`:`${metal} / Cu²⁺ displacement`):t?.metal||'Compare metal with carbon',`<div class="inventory-board"><span class="eyebrow">${electron?'ELECTRON ACCOUNT':'EXTRACTION EVIDENCE'}</span>${electron?`<div class="inventory-row"><span>${metal} atom → ${metal}²⁺ ion</span><small>${reveal?'Loses 2 electrons · oxidation':'Write the oxidation half-equation'}</small></div><div class="inventory-row"><span>Cu²⁺ ion → Cu atom</span><small>${reveal?'Gains 2 electrons · reduction':'Write the reduction half-equation'}</small></div><p class="inventory-outcome">${reveal?'2 electrons donated = 2 accepted':'Conserve every atom and total charge'}</p>`:`<div class="inventory-row"><span>${t?.evidence||'Below carbon: carbon may remove oxygen from the oxide.'}</span></div><p class="inventory-outcome">${reveal?{carbon:'Carbon reduction',other:'Another chemical route is needed',physical:'Physical separation of native metal'}[t.method]:'Choose a route and explain why'}</p>`}<p class="diagram-caption">${electron?'Symbolic charge bookkeeping, not a picture of electron paths or reaction mechanism.':'A decision model, not industrial apparatus or a practical procedure.'}</p></div>`,electron?'OIL RIG · ELECTRONS LOST / GAINED':'CHEMICAL VIABILITY BEFORE PROCESS COST');}
